    faq: {
      backToDashboard: "Back to Dashboard",
      pageTitle: "Frequently Asked Questions",
      pageSubtitle: "Quick answers to the most common questions about Bid.",
      q1: "What is Bid?",
      a1: "Bid is a private procurement platform designed for the Saudi market. It connects companies (requesters) that need goods or services with qualified vendors who can submit proposals. Requesters create tenders, invite vendors, and evaluate bids — all in one place.",
      q2: "Who can use Bid?",
      a2: "Bid is open to any company registered in Saudi Arabia. You can join as a requester (to publish tenders and source vendors) or as a vendor (to discover opportunities and submit bids). Many companies do both.",
      q3: "How do I publish a tender?",
      a3: "From your Dashboard, click New Tender. You can create one manually by filling in the title, scope, budget, deadline, and criteria — or let our AI assistant draft the brief for you. Once you're satisfied, publish the tender and share the invite link with your vendor network.",
      q4: "How do vendors find my tender?",
      a4: "You can share a private invite link directly with vendors you already know. Published tenders also appear in the public Marketplace, where vendors can discover and apply to open opportunities.",
      q5: "Is my tender information kept confidential?",
      a5: "Yes. Tenders are private by default — only vendors you explicitly invite can view the full details. When you publish to the Marketplace, the basic tender info becomes visible to all registered vendors, but submission details remain confidential.",
      q6: "How do I submit a bid as a vendor?",
      a6: "Open the tender from the Marketplace or follow the invite link shared by the requester. Read the full brief, then click Submit Bid and fill in the custom form the requester has prepared. You can attach documents, pricing, and any additional information they've requested.",
      q7: "Can I edit a tender after publishing it?",
      a7: "Yes. Open the tender from your Dashboard and use the Edit option. Note that vendors who have already received the invite link will see the updated information, so communicate any major changes to them directly.",
      q8: "What does company verification mean?",
      a8: "Verified companies have had their Commercial Registration (CR) and/or VAT documents reviewed by the Bid team. A verified badge on your profile signals to partners and vendors that you are a legitimate, registered business in Saudi Arabia.",
      q9: "How long does verification take?",
      a9: "Verification is typically completed within 1–3 business days after you upload your documents. You'll receive a notification once your status is updated.",
      q10: "Can I invite team members to my company workspace?",
      a10: "Yes. From your Dashboard, use the Invite Team feature to add colleagues by email. They'll receive an invitation and, once they accept, will share your company profile and can collaborate on tenders.",
      q11: "What is a Traction Link?",
      a11: "A Traction Link is a customisable public profile page for your company. You can add your logo, a bio, links, and highlight your services. Share it with potential partners as a lightweight company landing page.",
      q12: "How do I contact support?",
      a12: "Email us at info@bid.sa. Our support team is available Sunday through Thursday, 9 AM – 5 PM (AST). We aim to respond within one business day.",
      notFoundText: "Can't find what you're looking for?",
      emailSupportLink: "Email our support team",
      notFoundSuffix: "and we'll get back to you within one business day.",
    },
