      q1: "ما هو Bid؟",
      a1: "Bid منصة توريد خاصة مصممة للسوق السعودي. تربط الشركات (المشترين) المحتاجة لسلع أو خدمات بموردين مؤهلين يمكنهم تقديم العروض. ينشئ المشترون طلبات العروض (RFP)، ويدعون الموردين، ويقيمون العروض - كل ذلك في مكان واحد.",
      q2: "من يمكنه استخدام Bid؟",
      a2: "Bid متاحة لأي شركة مسجلة في المملكة العربية السعودية. يمكنك الانضمام كمشتري (لنشر طلبات العروض (RFP) والبحث عن موردين) أو كمورد (لاكتشاف الفرص وتقديم العروض). العديد من الشركات تقوم بالدورين معا.",
      q3: "كيف أنشر طلب عروض (RFP)؟",
      a3: "من لوحة التحكم، اضغط طلب عروض (RFP) جديد. يمكنك إنشاءه يدويا بتعبئة العنوان والنطاق والميزانية والموعد النهائي والمعايير - أو دع مساعدنا الذكي يصيغ الملخص لك. بعد الانتهاء، انشر الطلب وشارك رابط الدعوة مع شبكة مورديك.",
      q4: "كيف يجد الموردون طلبي للعروض (RFP)؟",
      a4: "يمكنك مشاركة رابط دعوة خاص مباشرة مع الموردين الذين تعرفهم. تظهر طلبات العروض (RFP) المنشورة أيضا في سوق المناقصات العام، حيث يمكن للموردين اكتشاف الفرص المفتوحة والتقدم لها.",
      q5: "هل تبقى معلومات طلب العروض (RFP) الخاص بي سرية؟",
      a5: "نعم. طلبات العروض (RFP) خاصة افتراضيا - فقط الموردون الذين تدعوهم صراحة يمكنهم رؤية التفاصيل الكاملة. عند النشر في سوق المناقصات، تصبح المعلومات الأساسية مرئية لجميع الموردين المسجلين، لكن تفاصيل التقديم تبقى سرية.",
      q6: "كيف أقدم عرضا كمورد؟",
      a6: "افتح طلب العروض (RFP) من سوق المناقصات أو اتبع رابط الدعوة الذي شاركه المشتري. اقرأ الملخص الكامل، ثم اضغط تقديم عرض واملأ النموذج المخصص الذي أعده المشتري. يمكنك إرفاق المستندات والتسعير وأي معلومات إضافية طلبها.",
      q7: "هل يمكنني تعديل طلب العروض (RFP) بعد نشره؟",
      a7: "نعم. افتح طلب العروض (RFP) من لوحة التحكم واستخدم خيار التعديل. لاحظ أن الموردين الذين استلموا رابط الدعوة بالفعل سيرون المعلومات المحدثة، لذا تواصل معهم مباشرة بشأن أي تغييرات جوهرية.",
      q8: "ماذا يعني توثيق الشركة؟",
      a8: "الشركات الموثقة راجع فريق Bid مستندات سجلها التجاري (CR) و/أو ضريبة القيمة المضافة الخاصة بها. تشير شارة التوثيق في ملفك للشركاء والموردين إلى أنك عمل تجاري مسجل وشرعي في المملكة العربية السعودية.",
      q9: "كم تستغرق عملية التوثيق؟",
      a9: "عادة ما يكتمل التوثيق خلال 1-3 أيام عمل بعد رفع مستنداتك. ستصلك إشعار بمجرد تحديث حالتك.",
      q10: "هل يمكنني دعوة أعضاء الفريق إلى مساحة عمل شركتي؟",
      a10: "نعم. من لوحة التحكم، استخدم ميزة دعوة الفريق لإضافة زملائك عبر البريد الإلكتروني. سيستلمون دعوة، وبعد قبولها سيشاركون ملف شركتك ويمكنهم التعاون في طلبات العروض (RFP).",
      q11: "ما هو رابط الإنضمام؟",
      a11: "رابط الإنضمام هو صفحة ملف عام قابلة للتخصيص لشركتك. يمكنك إضافة شعارك ونبذة وروابط وإبراز خدماتك. شاركه مع الشركاء المحتملين كصفحة تعريفية خفيفة لشركتك.",
