      s5Title: "5. الاحتفاظ بالبيانات",
      s5Body: "نحتفظ ببيانات الحساب وطلبات العروض (RFP) طالما أن حسابك نشط وحسب الحاجة لتقديم الخدمة. يمكنك طلب حذف حسابك بمراسلتنا؛ قد يحتفظ ببعض البيانات للامتثال للالتزامات النظامية أو أغراض التدقيق.",
      s6Title: "6. الأمان",
      s6Body: "نستخدم إجراءات معيارية في الصناعة لحماية بياناتك، منها تشفير TLS أثناء النقل، وكلمات مرور مجزأة، ومصادقة قائمة على JWT مع ضوابط وصول مقيدة بنطاق الشركة، وسجلات تدقيق للإجراءات الإدارية. لا يوجد نظام آمن بنسبة 100%، ولا يمكننا ضمان أمان مطلق.",
      s7Title: "7. حقوقك",
      s7Body: "لك الحق في الوصول إلى معلوماتك الشخصية أو تصحيحها أو حذفها. يمكنك تحديث معظم معلومات حسابك مباشرة من الإعدادات. لممارسة حقوق أخرى، تواصل معنا عبر العنوان أدناه.",
      s8Title: "8. ملفات تعريف الارتباط والتخزين المحلي",
      s8Body: "نستخدم ملفات تعريف الارتباط والتخزين المحلي للمتصفح لإبقائك مسجلا للدخول، وتذكر تفضيل لغتك، والحفاظ على حالة الجلسة. يمكنك مسح هذه البيانات في أي وقت من إعدادات متصفحك.",
      s9Title: "9. النقل الدولي للبيانات",
      s9Body: "قد تتم معالجة بياناتك على خوادم خارج المملكة العربية السعودية من قبل مزودي الخدمة لدينا. نتخذ خطوات لضمان وجود ضمانات مناسبة لهذه النقلات.",
      s10Title: "10. التعديلات",
