      insightTimelineVendorTip: "يحتاج الموردون إلى جداول زمنية واقعية لتقديم عروض دقيقة. المواعيد الضيقة قد تحد من مجموعة الموردين المؤهلين أو تزيد التكاليف.",
      insightTimelineBestPractice: "أضف وقت احتياطي للتأهيل. إذا كانت التواريخ مرنة، وضح ذلك لاستقبال عروض أفضل",
      insightBudgetTitle: "الميزانية",
