      insightBudgetVendorTip: "مشاركة معلومات الميزانية مسبقا يوفر الوقت لكلا الطرفين. يمكن للموردين فورا معرفة ما إذا كان المشروع يتوافق مع أسعارهم.",
      insightBudgetBestPractice: "نطاق الميزانية غالبا أفضل من المبلغ الدقيق - يمنح الموردين مجالا لاقتراح حلول إبداعية مع البقاء ضمن الحدود.",
      insightDeliverablesTitle: "المخرجات",
