      insightDeliverablesVendorTip: "المخرجات المحددة جيدا تساعد الموردين في تقديم جداول زمنية وتكاليف دقيقة. المخرجات الغامضة تؤدي في الغالب إلى أوامر تغيير وتأخيرات.",
      insightDeliverablesBestPractice: "اجعل كل مخرج قابلا للقياس. بدلا من \"مواد تدريبية\"، جرب \"دليل تدريبي 10 صفحات + 3 دروس فيديو (5 دقائق كل منها)\".",
      insightDescriptionTitle: "الوصف",
