      insightDescriptionVendorTip: "هنا يقرر المورد إذا كان بيقدم عرضه. أضف التفاصيل اللازمة ونظمها بشكل يسهل قراءته",
      insightDescriptionBestPractice: "نظم بفقرات قصيرة أو نقاط. غط الخلفية والنطاق والمتطلبات التقنية وأي قيود أو تفضيلات.",
      insightDeadlineTitle: "الموعد النهائي للتقديم",
