      insightDeadlineVendorTip: "أعط الموردين أسبوعين على الأقل للمشاريع البسيطة و4+ أسابيع للمشاريع المعقدة. المواعيد المتسرعة تقلل جودة العروض.",
      insightDeadlineBestPractice: "حدد الموعد النهائي في يوم عمل، في الصباح. تجنب الأعياد. انشر طلب العروض (RFP) في أقرب وقت ممكن لزيادة جودة الردود.",
      insightEvalTitle: "معايير التقييم",
      insightEvalDesc: "يحدد كيفية تسجيل ومقارنة عروض الموردين عبر الأبعاد المالية والخبرة والتقنية بفئات موزونة.",
      insightEvalVendorTip: "عندما يعرف الموردون أولوياتك، يستثمرون الجهد حيث يهم. هذا يؤدي إلى عروض أعلى جودة وأكثر صلة بالموضوع.",
      insightEvalBestPractice: "وزن المعايير حسب الأهمية (مثلا التقني 40%، المالي 35%، الخبرة 25%). حافظ على توازن الأوزان وتواصلها بوضوح.",
      insightAttachmentsTitle: "المرفقات",
