      insightAttachmentsVendorTip: "المرفقات تقلل الأسئلة المتكررة. كلما كان لدى الموردين سياق أكثر مسبقا، كانت عروضهم أسرع وأكثر دقة.",
      insightAttachmentsBestPractice: "سم الملفات بوضوح (مثلا \"Floor_Plan_v2.pdf\"). أدرج ملاحظة موجزة تشرح صلة كل مرفق بالموضوع.",
      insightVideoUrlTitle: "رابط الفيديو",
