      insightVideoUrlVendorTip: "فيديو من 2 إلى 5 دقائق يتيح للموردين رؤية الأشخاص والبيئة وراء طلب العروض (RFP)، مما يبني الثقة ويحسن جودة الاستجابات.",
      insightVideoUrlBestPractice: "اجعل مدة الفيديو أقل من 5 دقائق. تأكد من أن الرابط متاح للعموم (لا يتطلب تسجيل دخول). يوتيوب غير مدرج أو فيميو خياران مناسبان.",
      insightVendorReqsTitle: "متطلبات المورد",
