      insightVendorReqsVendorTip: "يساعد التمييز الواضح بين الإلزامي والمفضل الموردين على تقييم أنفسهم وتخطي طلبات العروض (RFP) التي لا يستوفونها، مما يحسن جودة العروض المقدمة.",
      insightVendorReqsBestPractice: "اجعل المتطلبات الإلزامية في حدها الأدنى وقابلة للإثبات (السجل التجاري، الزكاة، التأمينات). انقل التفضيلات الناعمة إلى المفضلة كي لا تضيق دائرة الموردين المؤهلين.",
