      insightMilestonesVendorTip: "يستخدم الموردون المراحل للتخطيط لتخصيص الفريق والموارد. المراحل الواضحة بمواعيد نهائية محددة تؤدي إلى عروض أكثر دقة ومفاجآت أقل.",
