interface I18nContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string, vars?: Record<string, string | number>) => string;
  isRtl: boolean;
}

// Persist context across HMR reloads so multiple queued saves never create
// a fresh context object that orphans the existing I18nProvider in the tree.
const _g = globalThis as Record<string, unknown>;
if (!_g.__i18nContext) {
  _g.__i18nContext = createContext<I18nContextType | null>(null);
}
const I18nContext = _g.__i18nContext as React.Context<I18nContextType | null>;

/**
 * Look a key up in the central dictionary for an explicit language.
 *
 * `useI18n().t` is the normal way to translate; this exists for the few places
 * that track their own language state outside the provider (the landing page
 * has its own AR/EN toggle) and so can't rely on the provider's language.
 */
export function translate(
  lang: Language,
  key: string,
  vars?: Record<string, string | number>,
): string {
  const keys = key.split('.');
  let value: any = translations[lang];
  for (const k of keys) {
    value = value?.[k];
  }
  let result = typeof value === 'string' ? value : key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      result = result.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return result;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const saved = localStorage.getItem('language');
    return (saved === 'ar' ? 'ar' : 'en') as Language;
  });

  const setLanguage = useCallback((lang: Language) => {
    setLanguageState(lang);
    localStorage.setItem('language', lang);

    // Persist to DB so emails and server-side features use the correct language
    const { user, token } = useAuthStore.getState();
    if (user && token) {
      fetch('/api/user/profile', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ name: user.name, language: lang }),
      }).catch(() => {});
    }
  }, []);

  // Keep the displayed language in sync with background updates to localStorage
  // (e.g. checkAuth() pulling the DB-stored preference on app load) — otherwise
  // the UI can keep showing one language while requests silently use another.
  useEffect(() => {
    const handler = (e: Event) => {
      const lang = (e as CustomEvent<Language>).detail;
      if (lang === 'ar' || lang === 'en') setLanguageState(lang);
    };
    window.addEventListener('bid:language-sync', handler);
    return () => window.removeEventListener('bid:language-sync', handler);
  }, []);

  useEffect(() => {
    const root = document.documentElement;
    if (language === 'ar') {
      root.dir = 'rtl';
      root.lang = 'ar';
    } else {
      root.dir = 'ltr';
      root.lang = 'en';
    }
  }, [language]);

  const t = (key: string, vars?: Record<string, string | number>): string =>
    translate(language, key, vars);

  const isRtl = language === 'ar';

  return (
    <I18nContext.Provider value={{ language, setLanguage, t, isRtl }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useI18n must be used within I18nProvider');
  }
  return context;
}

// Force full page reload on HMR so the singleton I18nContext is never duplicated
if (import.meta.hot) {
  import.meta.hot.accept(() => { window.location.reload(); });
}
